const r=[{id:"F01",title:"Sahih al-Bukhari 1 · Deeds and intentions",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Umar ibn al-Khattab narrates the Prophet's teaching about deeds and intentions.",limitation:"Religious source, not an empirical study. ODA's ordinary-task exercise is an interpretation, not the hadith's wording or a religious ruling. An app cannot judge sincerity or divine reward."},{id:"F02",title:"Sahih al-Bukhari 6491 · Intended and performed deeds",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"The passage narrated by Ibn Abbas describes the recording of intended and performed good and bad deeds.",limitation:"Its theological detail is not a psychological law. ODA's preparation and action records describe behavior; they cannot adjudicate religious reward."},{id:"F03",title:"The Qur'an · Al Imran 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Consultation, resolve, and reliance appear together in this verse.",limitation:"ODA draws a voluntary practical reflection. It does not establish a universal chronology where trust begins only after preparation, offer exhaustive interpretation, or guarantee an outcome."},{id:"F07",title:"Sunan Abi Dawud 4811 · Thanking people",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"The teaching narrated by Abu Hurayrah links thanking people with thanking Allah. The entry displays sahih grading by al-Albani.",limitation:"Religious teaching, not psychological efficacy evidence. The specific thank-you template is ODA's adaptation; source checking is not a new authentication or a requirement for unsafe contact."},{id:"F08",title:"The Qur'an · Al-Sharh 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"Ease alongside hardship offers a religious source of hope.",limitation:"No guarantee that an individual difficulty ends today or by a chosen date. ODA's support step is an adaptation, not a clinical effect or exhaustive interpretation."},{id:"F11",title:"Sahih al-Bukhari 6464 · Small regular deeds and moderation",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Aishah narrates teaching that emphasizes small regular deeds and moderation.",limitation:"The full passage also concerns deeds and salvation. An app streak measures neither faith nor salvation; the bounded kindness plan is ODA's adaptation."},{id:"F13",title:"Ano & Vasconcelles · 2005 · Religious coping and adjustment",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"Across 49 mostly observational studies, religious coping was associated with adjustment. Table 5 pooled Fisher z values were .33 [.30, .35] for positive coping/positive adjustment and .22 [.19, .24] for negative coping/negative adjustment.",limitation:"Not raw correlations or evidence of causation. Among 8,115 participants with reported affiliation, 57% were Protestant and 28% Catholic. Confounding, self-report, and limited transfer to Islamic practice remain. Research categories are not judgments about a learner."},{id:"F14",title:"Kirca et al. · 2023 · Expressed gratitude and well-being",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"Across 23 studies and 25 samples, expressed gratitude had a small average well-being benefit versus neutral comparisons: g = .22, 95% CI [.11, .33]. Against other well-being activities, g = .12 [−.02, .26].",limitation:"No demonstrated superiority over active comparisons or equivalence to therapy. Mostly nonclinical samples. The paper gives inconsistent participant totals, so neither total is used. No religious efficacy, compelled contact, or individual benefit guarantee."},{id:"F15",title:"Choi et al. · 2025 · Gratitude across cultures",url:"https://www.pnas.org/doi/10.1073/pnas.2425193122",type:"research",finding:"Across 145 papers and 163 samples in 28 countries, gratitude interventions had a small average effect on well-being, g = .19, 95% CI [.15, .22]. The future-study prediction interval was [−.21, .59].",limitation:"Largely nonclinical samples and varied procedures. Effects differ; the prediction interval includes zero. This does not validate one private sentence, predict one person's response, or establish Islamic gratitude as superior."},{id:"F16",title:"Curry et al. · 2018 · Kindness and the giver's well-being",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Across 27 studies and 4,045 participants, kind acts showed a modest average benefit for the giver's well-being, δ = .28, 95% CI [.16, .41].",limitation:"Heterogeneous, mostly nonclinical studies. No guarantee for every giver or recipient, no treatment effect or measure of religious reward, and no support for unlimited self-sacrifice. Undetected bias or moderators does not prove their absence."},{id:"F18",title:"Nelson et al. · 2016 · Prosocial behavior trial",url:"https://sonjalyubomirsky.com/wp-content/uploads/2024/03/Nelson-Layous-Cole-Lyubomirsky-2016.pdf",type:"research",finding:"The other-kindness arm prescribed three kind acts on one day each week for four weeks, followed by a two-week check. The pooled prosocial-versus-control flourishing growth estimate was d = .31, p = .05.",limitation:"Abstract N differs from randomized group totals: 473 versus 472, with 464 in growth analyses. Confidence interval and preregistration were not verified. The one-act ODA version differs from the trial and does not promise universal benefit."},{id:"F19",title:"Wang et al. · 2021 · Obstacle-linked plans and goal pursuit",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"Across 21 articles and 24 independent effects involving 15,907 participants, mental contrasting with if-then planning helped goal attainment on average: g = .336, 95% CI [.229, .443].",limitation:"Varied goals and delivery; publication-bias adjustment reduced the estimate. This does not validate a sincere intention alone, prayer causing success, a faith-specific checklist, or an optimal ten-minute preparation dose."},{id:"F20",title:"NIMH · 2026 · Caring for your mental health",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Persistent distress and difficulty with usual activities warrant professional support. Crisis needs immediate assistance.",limitation:"Public guidance, not diagnosis or evidence of a spiritual cause. No requirement to wait two weeks or finish a course before seeking help. Prayer and spiritual counsel do not replace healthcare."},{id:"faith-kindness",title:"Curry et al. · 2018 · Kindness and the giver's well-being",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Across 27 studies and 4,045 participants, kind acts showed a modest average benefit for the giver's well-being, δ = .28, 95% CI [.16, .41].",limitation:"Heterogeneous, mostly nonclinical studies. No guarantee for every giver or recipient, no treatment effect or measure of religious reward, and no support for unlimited self-sacrifice. Undetected bias or moderators does not prove their absence."}],t=[{schemaVersion:2,revision:2,id:"faith-1",courseId:"faith",locale:"en",title:"That good intention is still waiting",goal:"Carry out one useful piece of a commitment that expresses your chosen value.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"You meant to help. Give that promise one useful act today.",reason:{id:"faith-1-purpose-cost",label:"Which part would you choose without praise?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep my ordinary promise","Help within my real limits","Let my chosen value guide action"]},why:{id:"faith-1-why",label:"Which part would you choose without praise?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Bukhari's first hadith concerns deeds and intentions. Umar narrates the Prophet's teaching; this ordinary-task exercise is ODA's interpretation. Choose one commitment and let its purpose shape a useful act, rather than asking this app to judge your motives.","You may care about helping and also want recognition. You do not need to prove purity here. Choose what you want to serve, then perform one agreed piece. Preparation remains preparation when the act is unavailable. Keep spiritual reflection off ODA if you prefer. Optional answers are saved in your lesson or plan; coach sharing has separate consent controls."],example:{title:"Yusuf keeps a small promise",text:"Yusuf promised his neighbor a simple phone guide. At lunch he wants both to help and to look reliable. He chooses the helpful purpose and sends the agreed instructions for one call. The neighbor does not reply that afternoon. Yusuf records the message sent, keeps his motives private, and leaves whether it helped unknown."}},move:{invitation:"Give your promise one useful act. Edit the example to fit your actual agreement.",instructions:["Name the promised item, safe recipient, channel, and start event; private planning stays available.","Use your existing agreement; sending is the act, composing alone is preparation."],prompts:[],suggestions:{action:["Example: text Maya the agreed phone-setup link","Wash the two mugs I promised Yusuf","Send Sam the agreed appointment directions"],minimum:["Send Maya that agreed phone-setup link","Wash both agreed mugs","Send the agreed bus-stop instructions"],cue:["After I finish lunch","After our shared meal ends","When Sam's appointment reminder arrives"],place:["In our existing text thread","At our accessible kitchen sink","In our existing message thread"],minutes:[2,1],fallback:["Use our agreed email channel if texting fails","Agree another useful accessible cleanup task","Use our agreed accessible contact method"],observation:["Link sent; usefulness and reply remain unknown","Promised task performed, not only prepared","Instructions sent; no reply is still possible"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya the agreed phone-setup link",minimum:"Send Maya that agreed phone-setup link",cue:"After I finish lunch",place:"In our existing text thread",fallback:"Use our agreed email channel if texting fails",observation:"Link sent; usefulness and reply remain unknown",minutes:2},{action:"Wash the two mugs I promised Yusuf",minimum:"Wash both agreed mugs",cue:"After our shared meal ends",place:"At our accessible kitchen sink",fallback:"Agree another useful accessible cleanup task",observation:"Promised task performed, not only prepared",minutes:1},{action:"Send Sam the agreed appointment directions",minimum:"Send the agreed bus-stop instructions",cue:"When Sam's appointment reminder arrives",place:"In our existing message thread",fallback:"Use our agreed accessible contact method",observation:"Instructions sent; no reply is still possible",minutes:2}]},suggested:{action:"Example: text Maya the agreed phone-setup link",minimum:"Send Maya that agreed phone-setup link",minutes:2,cueHint:"After I finish lunch",placeHint:"In our existing text thread",obstacleHint:"Example: I explain my motives instead of sending",fallbackHint:"Use our agreed email channel if texting fails",observationHint:"Link sent; usefulness and reply remain unknown"},stopRule:"Choose only safe, voluntary acts within your limits.",accessibleAlternative:"Use your usual communication method; keep the plan off ODA."},result:{question:"Did you perform the useful act you chose?",observationPrompt:"What did you actually do, without sharing private motives?"},judgment:{primary:{id:"faith-1-decision",scenario:"Yusuf promised a classmate useful notes. They are ready. He wants to help and also wants recognition. Sending them is safe and welcome.",question:"Which choice serves the agreed commitment?",options:[{id:"private-reflection",text:"Reflect privately on his motives for another day before deciding whether to send the ready notes.",feedback:"Private reflection can be valuable. Here the safe, agreed resource is ready, so waiting for a cleaner motive delays the help. He can reflect without making purity a prerequisite."},{id:"send-agreed-notes",text:"Choose the helpful purpose and send the agreed notes without making praise a condition.",feedback:"This carries out the chosen commitment while allowing mixed motives. The record describes notes sent, not sincerity proven. Whether the classmate replies or benefits remains a separate observation."},{id:"explain-intention",text:"Explain his intention to the classmate first, then offer to send the notes after they respond.",feedback:"Explaining may feel honest, but asks the classmate to engage with his motives before receiving agreed help. He can keep reflection private and send the useful notes directly."}],bestOptionId:"send-agreed-notes"}},carry:{takeaway:"Give your chosen purpose a useful act. Keep the private intention yours.",followUp:{questionId:"faith-1-return",question:"Did the act serve your chosen purpose, or was it preparation?",observationPrompt:"What did you actually do, without sharing private motives?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Religious meaning stays distinct from the record",paragraphs:["In Sahih al-Bukhari 1, Umar ibn al-Khattab narrates the Prophet's teaching about deeds and intentions. ODA's exercise asks how a chosen purpose might shape an ordinary commitment. That is a modern educational interpretation, not the hadith's wording, an exhaustive explanation, or a religious ruling. [F01] You may reflect privately without writing a motive in the app.","Bukhari 6491 describes intended and performed deeds in a theological account of their recording. A behavioral log cannot simplify that account into a completion score or determine divine reward. [F02] “Prepared instructions” and “sent the agreed instructions” are different records of behavior. Neither tells ODA how sincere you were. A plan, a quiz answer, a streak, or a pause offers no basis for judging faith. If an action is unavailable, preparation can be chosen honestly, with the next real opportunity named when useful."]},{heading:"A plan gives the purpose somewhere to act",paragraphs:["A goal-planning review combined 21 articles with 24 independent effects. Contrasting a desired goal with a real obstacle and making an obstacle-linked plan helped goal attainment on average. Publication-bias adjustment reduced the estimated benefit, and delivery and goals varied. This is psychological evidence about a planning package, not proof of religious reward, prayer efficacy, or this course's particular checklist. [F19]","ODA adapts the idea by naming a useful act, a recognizable cue, a feasible place, and a response to a likely obstacle. Choose one ordinary commitment that matters in your week and use it through the course. Later lessons refine preparation, acknowledge real help, or add support only when those needs arise. Mixed motives need not become mandatory disclosure. Keep the plan privately if preferred; then ODA can remember your return choice, but cannot retrieve action details it never received."]}],sourceIds:["F01","F02","F19"]}},{schemaVersion:2,revision:2,id:"faith-2",courseId:"faith",locale:"en",title:"Still checking? Finish your part of the promise",goal:"Execute your ready commitment, or address one specific preparation gap with an honest stopping boundary.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Ready but still checking? Another check needs a real gap.",reason:{id:"faith-2-actual-gap-cost",label:"What gap remains, or what would another check postpone?",kind:"text",maxLength:160,optional:!0,suggestions:["Ready: perform my saved promise","Missing information: check only that gap","Unconfirmed timing: ask for agreement"]},why:{id:"faith-2-why",label:"What preparation is enough for your next real step?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Consultation, resolve, and reliance appear together in Al Imran 3:159. ODA uses this as a practical reflection on effort and trust, not a rule that trust begins only after preparation. An uncertain result remains uncertain even when you take your part seriously.","Return to your commitment. If a real gap appeared, choose one useful preparation and a stopping boundary. If you already have what you need, choose execution instead of another check. Count preparation by what you completed, not by reassurance. Prayer may accompany your choice privately; it is not a required technique or promised outcome."],example:{title:"Yusuf tests once",text:"Yusuf's neighbor asks whether the phone guide works on her model. He checks one needed instruction at his kitchen table and corrects it. He stops after the planned test and offers a safe call tomorrow. She has not confirmed yet. Yusuf records preparation completed, keeps prayer private, and does not report the later call as done."}},move:{invitation:"Ready: execute your promise. Real gap: choose one bounded preparation act.",instructions:["Keep your promise; use Adapt, Preparation only for a specific reported gap.","Name its stopping boundary and next use, or mark that use unconfirmed.","Saving preparation books only preparation; confirm execution's date and cue separately in your calendar."],prompts:[{id:"faith-2-gap-next-use",label:"For preparation, what gap and stopping boundary matter, and is the next use confirmed?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Example: test Maya’s contact-setting once; next call unconfirmed. Keep its date/cue off ODA or in the action."}],suggestions:{action:["Example: text Maya the ready phone-setup link","Make my agreed phone-guide call to Maya"],minimum:["Send Maya that ready agreed link","Explain the agreed first phone contact"],cue:["After I finish lunch","When our confirmed 6 p.m. call starts"],place:["In our existing text thread","In our existing accessible call"],minutes:[2,5],fallback:["Use our agreed email if texting fails","If Maya is unavailable, ask about another date"],observation:["Link sent; repeated checks versus new information","Call attempted; another date may remain unconfirmed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya the ready phone-setup link",minimum:"Send Maya that ready agreed link",cue:"After I finish lunch",place:"In our existing text thread",fallback:"Use our agreed email if texting fails",observation:"Link sent; repeated checks versus new information",minutes:2},{action:"Make my agreed phone-guide call to Maya",minimum:"Explain the agreed first phone contact",cue:"When our confirmed 6 p.m. call starts",place:"In our existing accessible call",fallback:"If Maya is unavailable, ask about another date",observation:"Call attempted; another date may remain unconfirmed",minutes:5}]},suggested:{action:"Example: text Maya the ready phone-setup link",minimum:"Send Maya that ready agreed link",minutes:2,cueHint:"After I finish lunch",placeHint:"In our existing text thread",obstacleHint:"Example: no information gap remains; I want certainty",fallbackHint:"Use our agreed email if texting fails",observationHint:"Link sent; repeated checks versus new information"},stopRule:"Stop at your boundary. Seek care now if distress disrupts life.",accessibleAlternative:"Use accessible rehearsal or consultation; prayer and writing stay optional."},result:{question:"Did you carry out the exact saved act?",observationPrompt:"What was executed, what was preparation, and is any next use still unconfirmed?"},judgment:{primary:{id:"faith-2-decision",scenario:"Yusuf has tested the instructions and confirmed the call time. He keeps checking the same steps because he still worries the call may go badly.",question:"Which choice fits the remaining need?",options:[{id:"longer-test",text:"Run another full test of the same instructions to feel more certain before the scheduled call.",feedback:"Another test can help when a specific gap remains. Here the steps are checked and the time confirmed. More repetition does not guarantee the call; keep the agreed execution opportunity."},{id:"cancel-call",text:"Replace tomorrow's call with another written guide so he can prepare without needing a live interaction.",feedback:"A written guide can be an accessible alternative if needed. Here the agreed call is ready and appropriate. Changing the format solely for certainty avoids the already feasible next step."},{id:"keep-opportunity",text:"End this preparation block, keep tomorrow's agreed call, and allow the result to remain uncertain.",feedback:"This keeps the useful preparation and its boundary without pretending certainty. Yusuf records what is ready and attempts the call at the agreed opportunity. Anxiety reduction is not the completion test."}],bestOptionId:"keep-opportunity"}},carry:{takeaway:"Finish the part you can do. Leave the outcome open and the next opportunity clear.",followUp:{questionId:"faith-2-gap-execution-return",question:"Did the saved act happen, and was any preparation tied to a real gap?",observationPrompt:"What was executed, what was preparation, and is any next use still unconfirmed?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Effort and trust without a rigid chronology",paragraphs:["Al Imran 3:159 brings consultation, resolve, and reliance together. ODA draws a voluntary practical pattern from that verse: ask about a real gap, make a considered choice, and carry out the part available to you. This is an interpretation for everyday practice. It does not say that trust is absent until a preparation checklist has been completed or that a requested result must follow. [F03]","This exercise does not prescribe how to trust. The stopping boundary concerns your ordinary preparation; you decide whether this voluntary religious reflection helps you make that practical choice. Your useful preparation might be one question, a checked instruction, or one rehearsal. End at the boundary you chose, then confirm the execution date and start event separately in your calendar, or mark them unconfirmed. Saving preparation books that act and its next-day review; it does not schedule the later call. A planned call is not a completed call. Voluntary prayer can accompany either stage and remains private; no devotional dose or faith score is assigned."]},{heading:"Enough preparation is a practical choice",paragraphs:["Obstacle-linked planning research supports concrete plans for goal pursuit on average across varied settings. It does not test this religious framing, establish a two-minute optimum, or show that repeated reassurance checks improve the outcome. [F19] ODA's stopping boundary is an adaptation intended to keep preparation tied to a real need. If information is missing, seek it. If the next step is unsafe or inaccessible, choose another route or appropriate support.","If distress, disrupted sleep, or trouble with usual activities persists, professional support is available alongside religious reflection. NIMH guidance does not establish a spiritual cause or require a two-week wait before asking for help. Crisis needs immediate support rather than another preparation exercise. [F20] A knowledgeable religious adviser may be an optional source of spiritual counsel, but is not a replacement for healthcare. Record the preparation you actually did; leave emotional certainty and external success outside its completion conditions."]}],sourceIds:["F03","F19","F20"]}},{schemaVersion:2,revision:2,id:"faith-3",courseId:"faith",locale:"en",title:"Someone helped. Name what they actually did.",goal:"Write one truthful acknowledgment of support for your continuing commitment; sharing stays optional.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Help arrived amid disagreement? Thank them without pretending everything else is fine.",reason:{id:"faith-3-acknowledgment-tradeoff",label:"What makes thanks awkward, and which act can you honestly acknowledge?",kind:"text",maxLength:160,optional:!0,suggestions:["Name real help without settling disagreement","Keep contact safe and optional","If no help occurred, continue my promise"]},why:{id:"faith-3-why",label:"Whose safe contribution helped the commitment you chose?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Thanking people is linked to thanking Allah in the teaching narrated in Abu Dawud 4811. The short note here is ODA's adaptation. Name one real contribution that helped your chosen commitment. You do not need to describe the whole relationship as good.","Research finds a small average well-being benefit from expressed gratitude, with variable results. It does not prove therapy equivalence or require feeling better. Choose a related note; any unfinished promise remains separate. Name the act and benefit privately. Writing and voluntary sending are separate. If no help occurred, continue your promise instead."],example:{title:"Yusuf's truthful note",text:"Yusuf's sister lent him a clear phone guide. They still disagree about another family issue. He writes privately: “Your guide helped me explain the first call to our neighbor.” He keeps the note that evening because he is unsure about contact. The disagreement remains. He records only a note written, without storing its contents in ODA."}},move:{invitation:"Name real help; keep this related note separate from your promise.",instructions:["Use Plan a separate related act; any unfinished promise remains separate.","Name the observed act and benefit; share only through safe, welcome contact.","No help occurred? Continue your promise. Under pressure, acknowledge only that help or pause."],prompts:[],suggestions:{action:["Example: privately thank Maya for her guide","Privately thank Sam for Tuesday's covered shift"],minimum:["Write: Maya's guide helped explain one contact","Write: Sam's cover allowed my agreed appointment"],cue:["After I finish lunch","After agreed shift ends"],place:["In my own private notes","In a quiet accessible private space"],minutes:[2,1],fallback:["Speak only the act and benefit privately","Name only that shift; leave disagreement unresolved"],observation:["Note written or spoken; original promise remains outstanding","Acknowledgment made; original promise remains separate"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: privately thank Maya for her guide",minimum:"Write: Maya's guide helped explain one contact",cue:"After I finish lunch",place:"In my own private notes",fallback:"Speak only the act and benefit privately",observation:"Note written or spoken; original promise remains outstanding",minutes:2},{action:"Privately thank Sam for Tuesday's covered shift",minimum:"Write: Sam's cover allowed my agreed appointment",cue:"After agreed shift ends",place:"In a quiet accessible private space",fallback:"Name only that shift; leave disagreement unresolved",observation:"Acknowledgment made; original promise remains separate",minutes:1}]},suggested:{action:"Example: privately thank Maya for her guide",minimum:"Write: Maya's guide helped explain one contact",minutes:2,cueHint:"After I finish lunch",placeHint:"In my own private notes",obstacleHint:"Example: I feel pressure to settle our disagreement",fallbackHint:"Speak only the act and benefit privately",observationHint:"Note written or spoken; original promise remains outstanding"},stopRule:"Do not contact an unsafe person or erase harm to give thanks.",accessibleAlternative:"Speak or type privately; recipient and contents stay optional."},result:{question:"Did you make the acknowledgment you chose?",observationPrompt:"Was it written, spoken privately, or shared by choice?"},judgment:{primary:{id:"faith-3-honest-acknowledgment-decision",scenario:"Sam covered Yusuf’s Tuesday shift, allowing a care appointment. Their separate disagreement remains. Contact is safe. Sam has said they cannot cover next week and does not want another request now. Yusuf wants to acknowledge Tuesday’s help.",question:"Which acknowledgment respects the facts and Sam’s stated limit?",options:[{id:"faith-3-misstated-help",text:"Thank Sam for arranging the care appointment and covering Tuesday’s shift so Yusuf could attend.",feedback:"Sam covered the shift; the scenario does not say Sam arranged the appointment. Keep the acknowledgment to the act and benefit you observed. Accurate thanks can coexist with an unresolved disagreement."},{id:"faith-3-specific-thanks",text:"Thank Sam for Tuesday’s cover and name the care appointment it made possible, leaving the disagreement unresolved.",feedback:"This names the observed act and benefit while respecting the current boundary. Mixed feelings may remain. Yusuf can keep the note private or share voluntarily; neither his original promise nor the disagreement is settled."},{id:"faith-3-new-request",text:"Thank Sam for Tuesday’s cover and explain why another covered shift next week would also help.",feedback:"Thanks and a transparent request can coexist. Here Sam explicitly declined another request now, so adding one disregards that limit. Acknowledge Tuesday’s help and seek any future coverage elsewhere."}],bestOptionId:"faith-3-specific-thanks"}},carry:{takeaway:"Acknowledge the real help. A note does not complete your original promise or settle every hurt.",followUp:{questionId:"faith-3-related-note-return",question:"Was the related acknowledgment truthful and safe, while the original promise stayed separately recorded?",observationPrompt:"Was the note written, spoken, or shared? What original act remains outstanding?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"A specific note is an adaptation",paragraphs:["Abu Dawud 4811 links thanking people with thanking Allah. The listed entry attributes the narration to Abu Hurayrah and displays a sahih grading by al-Albani. ODA's practical note is a modern adaptation, not the wording of that source or a new religious authentication. [F07] You can acknowledge one contribution without sharing private religious reflection or turning the app into a judge of gratitude.","The template names what someone did and the benefit you observed. It is a writing aid, not a verified claim that specific thanks are scientifically superior to general thanks. A safe person's help can be real while disagreement or hurt remains real. Keep those facts separate. Writing privately and sending a message are different actions; record whichever you actually chose. A private note cannot be described as a delivered gratitude intervention, and an unanswered message does not cancel the act you performed."]},{heading:"Small average effects, no treatment equivalence",paragraphs:["The 2023 expressed-gratitude review included 23 studies and 25 samples. Compared with neutral conditions, the average well-being effect was small: g = .22, with a 95% confidence interval of .11 to .33. Against other well-being activities, the interval for the difference included zero. Those activities were not necessarily established clinical treatments, and a nonsignificant superiority test does not establish equivalence to therapy. The paper's inconsistent participant totals are withheld. [F14]","A larger 2025 gratitude review also found a small average benefit, but its prediction interval for a future study included zero. Results varied across procedures and settings. [F15] Neither review proves a religious teaching, guarantees a personal benefit, or validates this private one-sentence format. You may finish the act without feeling positive. Use the note if it serves your chosen relationship or life direction; change or stop the practice if it feels unhelpful or coercive."]}],sourceIds:["F07","F14","F15"]}},{schemaVersion:2,revision:2,id:"faith-4",courseId:"faith",locale:"en",title:"Carrying it alone? Ask for one clear thing.",goal:"Make one safe practical care request, with a fallback if support is unavailable.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Carrying it alone? Make one clear care request without judging your faith.",reason:{id:"faith-4-request-boundary-cost",label:"What makes a safe request difficult, and what boundary would make it possible?",kind:"text",maxLength:160,optional:!0,suggestions:["Ask for one defined task","Limit what private details I share","Use care without a productivity condition"]},why:{id:"faith-4-why",label:"What care would make your continuing commitment safer?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Al-Sharh's verses about ease alongside hardship offer religious hope, not a deadline for relief. Focus on the next manageable moment. Care may be the whole valued action. A related support request leaves your unfinished promise separate; asking does not perform that promise.","Religious coping research describes associations, not proof that a spiritual practice causes relief or struggle means weak faith. Make one specific request to a safe person or professional. If they cannot help, use a suitable fallback. The request is your action; their availability is an outcome. Private doubts and devotional details do not belong in a score."],example:{title:"Yusuf asks again elsewhere",text:"Yusuf is exhausted after caregiving and cannot manage the neighbor's agreed call tonight. He asks his brother to cover one household task; his brother cannot. Yusuf contacts another trusted relative and offers the neighbor a later call. Help is still unconfirmed. He records the request made and takes available rest, without judging his faith."}},move:{invitation:"For routine support, name one safe, specific request.",instructions:["Urgent need: seek immediate crisis or emergency help before scheduling any routine experiment.","Use Plan a separate related act; name help, recipient, channel, and time.","If declined, choose another available service or safe care; your unfinished promise remains separate."],prompts:[],suggestions:{action:["Example: text Maya for evening dishwashing help","Call my clinic about available appointment times"],minimum:["Ask Maya to wash dishes at 7","Ask the clinic for one suitable appointment"],cue:["After the agreed 6 p.m. care handover","When the clinic's phone line opens"],place:["In our existing text thread","At my accessible private phone space"],minutes:[2,5],fallback:["If declined, leave nonessential dishes and rest","Use the clinic's accessible booking channel"],observation:["Request sent; help received remains a separate fact","Contact made; appointment may remain unconfirmed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya for evening dishwashing help",minimum:"Ask Maya to wash dishes at 7",cue:"After the agreed 6 p.m. care handover",place:"In our existing text thread",fallback:"If declined, leave nonessential dishes and rest",observation:"Request sent; help received remains a separate fact",minutes:2,kind:"support"},{action:"Call my clinic about available appointment times",minimum:"Ask the clinic for one suitable appointment",cue:"When the clinic's phone line opens",place:"At my accessible private phone space",fallback:"Use the clinic's accessible booking channel",observation:"Contact made; appointment may remain unconfirmed",minutes:5,kind:"support"}]},suggested:{kind:"support",action:"Example: text Maya for evening dishwashing help",minimum:"Ask Maya to wash dishes at 7",minutes:2,cueHint:"After the agreed 6 p.m. care handover",placeHint:"In our existing text thread",obstacleHint:"Example: the first person cannot help tonight",fallbackHint:"If declined, leave nonessential dishes and rest",observationHint:"Request sent; help received remains a separate fact"},stopRule:"Crisis or self-harm thoughts need immediate local crisis help; immediate danger needs emergency services. Seek help now, before scheduling.",accessibleAlternative:"Use an accessible contact method; prayer never replaces needed care."},result:{question:"Did you make the request or take the care step?",observationPrompt:"What care happened, and what remains unmet?"},judgment:{primary:{id:"faith-4-available-care-decision",scenario:"Leila needs help transferring her dependent tonight; doing it alone is unsafe. The dependent is safely seated now. A relative declined. The care service’s staffed line is open and can arrange a worker tonight; routine email is answered tomorrow. Leila can safely wait seated while calling.",question:"Which request addresses tonight’s need most directly?",options:[{id:"faith-4-staffed-line",text:"Call the staffed care line, request tonight’s transfer help, and keep the dependent safely seated while waiting.",feedback:"This names the immediate practical task and uses a source available tonight. Calling is the act; confirmed help is separate. If safety changes while waiting, seek appropriate immediate emergency assistance."},{id:"faith-4-general-call",text:"Call the staffed line to describe her exhausting week and ask what general caregiving support it offers.",feedback:"Describing the wider burden may help ongoing care. Tonight’s transfer need is more specific and cannot be deferred. Lead with that task, then discuss continuing support if time and safety permit."},{id:"faith-4-email-and-wait",text:"Email the exact transfer request and keep the dependent safely seated while waiting for tomorrow’s routine response.",feedback:"The email is specific and avoids an unsafe solo transfer. Its reply timing does not meet tonight’s need. Use the staffed line now; record whether suitable help is actually confirmed."}],bestOptionId:"faith-4-staffed-line"}},carry:{takeaway:"A clear request is your act. Available support is an outcome to check and follow up.",followUp:{questionId:"faith-4-related-support-return",question:"Was the care request made, was help available, and what need remains unmet?",observationPrompt:"What request or care happened? Which original promise remains separately outstanding?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Hope can accompany practical care",paragraphs:["Al-Sharh 94:5–6 offers a religious source of hope through ease alongside hardship. It does not establish that your difficulty ends today, on a selected date, or in the way you want. ODA's support request is a practical adaptation, not a ruling or a clinical effect inferred from the verses. [F08] You may reflect privately or simply choose a care step.","A manageable moment can be much smaller than a day. Ask what immediate need can be named and what safe person or service could respond. An unavailable first contact is information about that contact, not evidence that you should carry everything alone. Rest or professional care can be the full valued action; neither needs to earn permission through productivity. A boundary may protect you better than another commitment. Do not use patience, gratitude, or forgiveness as an instruction to tolerate abuse or unsafe contact."]},{heading:"Research categories cannot judge your faith",paragraphs:["The religious-coping review combined 49 studies with 13,512 participants, largely observational and self-reported. Its familiar .33 and .22 values are pooled Fisher z values, not raw correlations. Among the 8,115 participants whose affiliation was reported, 57% were Protestant and 28% Catholic. That denominator does not describe every participant. The associations do not establish causation or the efficacy of Islamic practice. Research labels must not become a verdict about a learner's faith. [F13]","NIMH guidance supports professional help for persistent distress and impaired usual functioning; asking sooner is allowed. Prayer or optional spiritual counsel can accompany healthcare, but cannot replace needed treatment. Crisis or self-harm thoughts call for immediate crisis support: call or text 988 in the US; immediate life-threatening danger calls for emergency services. Elsewhere use local crisis or emergency services. [F20] Do not wait for a course result or a duration threshold before seeking urgent care."]}],sourceIds:["F08","F13","F20"]}},{schemaVersion:2,revision:2,id:"faith-5",courseId:"faith",locale:"en",title:"Be generous without breaking another promise",goal:"Retain your useful commitment, confirm wanted help, and date one attempt with a numeric time boundary.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"A helpful call keeps getting longer. Choose kindness your actual week can hold.",reason:{id:"faith-5-purpose-cost",label:"What will you limit so this commitment stays feasible?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep care within my capacity","Protect another existing promise","Offer useful help without requiring thanks"]},why:{id:"faith-5-why",label:"What will you limit so this commitment stays feasible?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Look back at the same commitment: what did you do, what helped, and what did it cost? Keep the useful act and any necessary support. Aishah's narration in Bukhari emphasizes regular small deeds and moderation. That teaching does not make an app streak a measure of faith.","Kindness studies find a modest average benefit for the giver, not a guarantee or permission to ignore limits. Retain your useful act, confirm it is wanted, and put its numeric boundary in Action or Minimum. Date one occurrence. Repetition is only considered here; tomorrow’s review helps choose another dated opportunity."],example:{title:"Yusuf ends on time",text:"Yusuf’s records show that helping with one phone contact is useful, but evenings conflict with care. His neighbor agrees to a two-minute text exchange after Saturday lunch. Yusuf sends the contact instructions and ends within two minutes. Another question remains. He records the useful message and limit kept. Next Saturday is considered, with no agreement yet."}},move:{invitation:"Keep your useful promise; date one wanted task with a numeric end boundary.",instructions:["Keep the original promise; change its size or timing only by deliberate agreement.","Store the boundary in Action or Minimum, or keep all details off ODA."],prompts:[],suggestions:{action:["Example: text Maya instructions within 2 minutes","Call Sam: one phone contact, 5 minutes maximum"],minimum:["Send agreed contact instructions within 2 minutes","Explain one agreed contact within 5 minutes"],cue:["After our agreed lunch ends","When Wednesday's confirmed 6 p.m. call starts"],place:["In our existing text thread","In our existing accessible call"],minutes:[2,5],fallback:["If more is needed, offer another confirmed date","If more is needed, agree a separate opportunity"],observation:["Agreed help sent, welcome, and two-minute limit kept","Contact explained, welcome, and five-minute limit kept"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya instructions within 2 minutes",minimum:"Send agreed contact instructions within 2 minutes",cue:"After our agreed lunch ends",place:"In our existing text thread",fallback:"If more is needed, offer another confirmed date",observation:"Agreed help sent, welcome, and two-minute limit kept",minutes:2},{action:"Call Sam: one phone contact, 5 minutes maximum",minimum:"Explain one agreed contact within 5 minutes",cue:"When Wednesday's confirmed 6 p.m. call starts",place:"In our existing accessible call",fallback:"If more is needed, agree a separate opportunity",observation:"Contact explained, welcome, and five-minute limit kept",minutes:5}]},suggested:{action:"Example: text Maya instructions within 2 minutes",minimum:"Send agreed contact instructions within 2 minutes",minutes:2,cueHint:"After our agreed lunch ends",placeHint:"In our existing text thread",obstacleHint:"Example: the request expands beyond our agreed two minutes",fallbackHint:"If more is needed, offer another confirmed date",observationHint:"Agreed help sent, welcome, and two-minute limit kept"},stopRule:"Protect health, sleep, money, and existing commitments. Unsafe help or contact is not required.",accessibleAlternative:"Use accessible help or choose rest, support, or a boundary."},result:{question:"Did you perform the bounded act you chose?",observationPrompt:"What was useful and welcome, and did your limit hold?"},judgment:{primary:{id:"faith-5-task-boundary-decision",scenario:"Nadia’s neighbor wants help using one phone contact before a Thursday appointment. Wednesday offers ten free minutes before Nadia’s fixed care duty. The neighbor welcomes a ten-minute call; texts are hard to read. Saturday offers twenty minutes, after the appointment.",question:"Which next plan fits the useful task and both people’s constraints?",options:[{id:"faith-5-saturday-call",text:"Offer Saturday’s twenty-minute call so the neighbor has more time to learn the phone steps.",feedback:"Saturday protects Nadia’s care duty and allows more practice. It misses the Thursday need. Use the agreed Wednesday window for this contact; consider Saturday separately for later questions."},{id:"faith-5-text-steps",text:"Send the contact steps by text on Wednesday, keeping her care duty and giving the neighbor written instructions.",feedback:"A text would preserve time and provide a reference. The neighbor finds texts hard to read, so this format may not meet the actual need. The agreed short call is accessible here."},{id:"faith-5-ten-minute-call",text:"Use Wednesday’s agreed ten-minute call for the one contact, state the end time, and stop before care duty.",feedback:"This meets the pre-appointment need through a welcome accessible method while protecting care. Record the contact explained and limit kept. Another question remains a separate opportunity, not an obligation to overrun."}],bestOptionId:"faith-5-ten-minute-call"}},carry:{takeaway:"Keep one welcome act that fits your week. Let usefulness and cost guide the next choice.",followUp:{questionId:"faith-5-bounded-occurrence-return",question:"Was the agreed task useful and welcome, and did its numeric boundary protect your other commitments?",observationPrompt:"What useful act happened, was the limit kept, and is another date confirmed?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Regular does not mean unlimited",paragraphs:["Bukhari 6464 emphasizes small regular deeds and moderation in a narration attributed to Aishah. The fuller passage also concerns deeds and salvation. ODA draws a voluntary practical reflection about a sustainable act; it cannot judge either religious worth or salvation from a count. A private intention, devotional practice, skipped occasion, or app streak is not a faith score. [F11]","Review the action and support records you chose to keep. Which piece genuinely served the purpose? What time, effort, or displaced commitment did it require? Retain that useful piece rather than adding another ritual. Consider daily or weekly repetition, but date one actual occurrence. This plan books that occurrence and its next-day return, not a recurring cadence. Confirm help is wanted, state a feasible boundary, and keep it. If the need exceeds your capacity, a smaller offer, a referral, rest, or stopping may be more responsible than promising unlimited help. Thanks and warm feelings are not completion conditions."]},{heading:"What kindness research actually tested",paragraphs:["The 2018 kindness review combined 27 studies involving 4,045 participants. Kind acts produced a modest average well-being benefit for the giver, with heterogeneous samples and procedures. This does not guarantee benefit to every giver or recipient, measure religious reward, or validate unlimited self-sacrifice. Undetected moderators or publication bias do not prove none exists. [F16]","In a separate trial, the other-kindness arm prescribed three acts on one day each week for four weeks, followed by a two-week check. It did not prescribe six weeks of acts. The paper's abstract and randomized totals differed, and its main growth analyses used a smaller set. [F18] ODA's one-act, capacity-bounded plan is a different adaptation. Schedule the next real opportunity only if it still fits. Tomorrow's return checks usefulness, welcome, and cost; it does not require repeating today or keeping a religious streak."]}],sourceIds:["F11","F16","F18"]}}];function a(e,i,n){return{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Record what actually happened and review this same experiment tomorrow."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:e.judgment.primary.options.map(o=>o.text),correct:i,feedback:e.judgment.primary.options[i].feedback,takeaway:e.carry.takeaway,sources:e.id==="faith-5"?[...e.goDeeper.sourceIds,"faith-kindness"]:e.goDeeper.sourceIds,photo:n}}const s={id:"faith",title:"You mean to help. Let faith shape one ordinary promise",subtitle:"5 voluntary lessons. Try one meaningful commitment, keep reflection private, and make room for care and limits.",description:"Connect voluntary Islamic reflection with one chosen ordinary act, then revise it using preparation, truthful thanks, support, and honest boundaries.",scope:"Islamic reflection and voluntary daily practices. Religious sources and psychological research are shown separately; anxiety or struggle is not treated as a lack of faith. This is not a religious ruling and not a substitute for mental health care. If you are in crisis or thinking about harming yourself, contact your local emergency number.",outcome:"A tried or paused commitment, private reflection, and a dated next step or support.",photo:{id:"1767396024869-756a346dc39d",alt:"A mosque courtyard with arched doorways and trees"},lessons:[a(t[0],1,{id:"1778616364918-34490657598f",alt:"A man holding prayer beads"}),a(t[1],2,{id:"1590682680695-43b964a3ae17",alt:"Hands planting a seedling in soil"}),a(t[2],1,{id:"1634906346143-aacbc4c02fec",alt:"A thank-you note on a table next to a pair of glasses"}),a(t[3],0,{id:"1570739260082-39a84dae80c8",alt:"A lit lantern on a wooden table"}),a(t[4],2,{id:"1710092784814-4a6f158913b8",alt:"A woman handing a plate of food to another woman"})]};export{s as COURSE,t as LESSONS_V2,r as SOURCES};
